INSERT INTO interview_banks (bank_id, version, content_hash, status, family, course, sort_index, difficulty, titles, descriptions, module_refs, question_count, calibration, imported_at, published_at)
VALUES ('0-fullstack-mastery/1-database-integration-and-caching', '231d8cc57-stem1', '68406d22c4a6d8c33479b0b4f2cfba63e7f43de90e9496019840339793901dc6', 'published', 'technical', '0-fullstack-mastery', 1, 'medium', $iv${"vi":"Phỏng vấn: Tích hợp database & caching - SQL vs NoSQL, ánh xạ quan hệ với ORM, mô hình hoá document, và chiến lược cache Redis","en":"Interview: Database integration & caching - SQL vs NoSQL, relational mapping with an ORM, document modeling, and Redis cache strategy"}$iv$::jsonb, $iv${"vi":"Ngân hàng gồm 15 câu phỏng vấn tư duy, trải khắp 7 loại phỏng vấn nói (theory, scenario, reasoning, debug, review, optimize, design-lite), bao phủ 4 bài học của module: lựa chọn giữa mô hình lưu trữ quan hệ và document (schema nằm ở đâu, ACID vs BASE, polyglot persistence), mô hình quan hệ ánh xạ qua ORM (cardinality 1-1/1-N/N-N, quyền sở hữu foreign-key, eager vs lazy loading, N+1), mô hình document qua ODM (embed vs reference, tính atomic trong một document, các toán tử update atomic), và chiến lược caching với Redis (cache-aside, ba tầng cache, TTL, invalidation, dữ liệu stale, đụng độ key). Module đa ngôn ngữ (TypeScript/Java/C#/Go) — các khái niệm phổ quát, NestJS + TypeORM/Mongoose chỉ là ví dụ minh hoạ.","en":"A 15-question reasoning-focused interview bank spanning 7 spoken-interview categories (theory, scenario, reasoning, debug, review, optimize, design-lite) for the module's four lessons: choosing between the relational and document storage models (schema location, ACID vs BASE, polyglot persistence), the relational model mapped through an ORM (cardinality 1-1/1-N/N-N, foreign-key ownership, eager vs lazy loading, N+1), the document model through an ODM (embed vs reference, single-document atomicity, atomic update operators), and caching strategy with Redis (cache-aside, three cache tiers, TTL, invalidation, stale data, key collisions). Multi-language module (TypeScript/Java/C#/Go) — the concepts are universal; NestJS + TypeORM/Mongoose are only the illustrating examples."}$iv$::jsonb, ARRAY['1-database-integration-and-caching']::text[], 15, '{"mode":"dev-seed"}'::jsonb, now(), now())
ON CONFLICT (bank_id, version) DO NOTHING;

INSERT INTO interview_questions (bank_id, bank_version, question_id, sort_index, is_premium, family, tier, kind, tags, competency, leadership_tier, bodies, interviewer, grading)
VALUES ('0-fullstack-mastery/1-database-integration-and-caching', '231d8cc57-stem1', '0-fullstack-mastery/1-database-integration-and-caching/0', 0, false, 'technical', 'junior', 'theory', ARRAY['flexible-schema', 'schema-location', 'sql-vs-nosql']::text[], NULL, NULL, $iv${"agnostic":{"vi":{"prompt":"Một đồng nghiệp trong team đề xuất dùng NoSQL cho một tính năng mới, với lý do \"để khỏi cần schema luôn cho đỡ việc\". Hãy nói to phần tư duy của bạn: schema thực sự đi đâu trong từng mô hình lưu trữ. Ở một relational store, cột và kiểu dữ liệu được khai báo trước, và chính database từ chối một bản ghi sai hình dạng ngay lúc ghi. Ở một document store, engine chấp nhận document ở bất kỳ shape nào, còn các ràng buộc cấu trúc lại do tầng mapping phía application enforce. Giải thích cái bạn được và cái âm thầm dịch chuyển sang team bạn. Nói theo kiểu bất khả tri ngôn ngữ.","givenCode":null,"diagram":null},"en":{"prompt":"A teammate proposes NoSQL for a new feature, arguing \"so we don't need a schema at all — less work.\" Talk through your reasoning out loud: where the schema actually goes in each storage model. In a relational store the columns and types are declared up front, and the database itself rejects a wrongly-shaped record at write time. In a document store the engine accepts any shape, while the structure constraints are enforced by the application-side mapping layer instead. Explain what you gain and what quietly moves onto your team instead (the consistency responsibility). Stay language-agnostic.","givenCode":null,"diagram":null}}}$iv$::jsonb, $iv${"vi":{"followUps":["Nếu một bug ở tầng validation phía application làm lọt một document sai shape vào store, engine có chặn lại không? Điều đó nói lên gì về nơi thực sự đặt trách nhiệm?","Với dữ liệu thực sự quan hệ chặt (nhiều-nhiều, cần transaction mạnh) — chọn NoSQL \"để khỏi cần schema\" có còn hợp lý không, vì sao?"],"hints":["Tự hỏi: khi bạn ghi một document \"sai hình dạng\" vào store, ai là người từ chối nó — engine hay code phía application?","Đi qua đúng hai phía: SQL (schema khai báo Ở ĐÂU, ai enforce, hệ quả) và NoSQL (schema khai báo Ở ĐÂU, ai enforce, bằng chứng là metadata engine tự thêm) — rồi chốt điều gì thực sự bị đánh đổi."]},"en":{"followUps":["If a bug in the application-side validation layer lets a wrongly-shaped document slip into the store, does the engine block it? What does that say about where the responsibility actually sits?","For data that is genuinely relational (many-to-many, needing strong transactions) — does picking NoSQL \"to skip the schema\" still make sense, and why?"],"hints":["Ask yourself: when you write a \"wrongly-shaped\" document into the store, who rejects it — the engine or the application-side code?","Walk through exactly two sides: SQL (WHERE the schema is declared, who enforces it, the consequence) and NoSQL (WHERE the schema is declared, who enforces it, the evidence being the metadata the engine adds on its own) — then name what actually gets traded away."]}}$iv$::jsonb, $iv${"locales":{"vi":{"rubric":["Chỉnh lại đúng gốc: schema không biến mất — nó dịch chuyển từ tầng database sang tầng application (một lớp ODM/validation enforce field bắt buộc/kiểu dữ liệu; bản thân engine chấp nhận document ở bất kỳ shape nào).","Giải thích phía SQL: cột + kiểu được khai báo trước, database enforce ràng buộc ngay lúc ghi — một bản ghi sai kiểu hoặc thiếu cột bị từ chối tại tầng lưu trữ, nên mọi consumer được đảm bảo cùng một shape.","Giải thích phía document kèm bằng chứng cụ thể: engine lưu được document ở bất kỳ shape nào, và tự thêm metadata riêng của nó (id tự sinh, timestamps, version field) mà application chưa từng khai báo — bằng chứng engine không enforce shape của app.","Gọi tên chính xác đánh đổi: đổi shape không cần migration, nhưng trách nhiệm giữ nhất quán dữ liệu dịch chuyển từ database vào application code.","Chốt bằng đúng sắc thái: \"không schema\" không bao giờ có nghĩa \"không cấu trúc\" — application vẫn phụ thuộc vào một cấu trúc, câu hỏi chỉ là tầng nào đứng ra canh giữ nó."],"checklist":[{"text":"States the core insight: flexibility means the schema relocates, it does not disappear.","dimension":"technical","critical":true,"scoreBand":15},{"text":"Explains that in SQL the schema lives INSIDE the database: columns and types are declared up front, and the database enforces the constraint at write time, rejecting a wrong record right at the storage layer.","dimension":"technical","critical":true,"scoreBand":15},{"text":"Notes every consumer of a relational store is guaranteed one shape, at the price of a migration whenever the shape changes.","dimension":"technical","critical":false,"scoreBand":10},{"text":"Explains that in NoSQL the engine can store a document of any shape — visible from the stored document carrying the engine's own metadata (auto-generated id, version field, timestamps) that the application never declared.","dimension":"technical","critical":true,"scoreBand":15},{"text":"Explains the structure that DOES exist is instead imposed by the application-side schema layer (required/trim/type constraints).","dimension":"technical","critical":false,"scoreBand":10},{"text":"States the trade-off: evolve the shape freely with no migration needed, but the responsibility for guarding consistency shifts into code.","dimension":"problemSolving","critical":true,"scoreBand":15},{"text":"Warns a bug in the application layer can write garbage that the engine will happily accept.","dimension":"problemSolving","critical":false,"scoreBand":10},{"text":"Concludes you should choose the engine based on who you want holding the schema, not on \"less work\".","dimension":"communication","critical":false,"scoreBand":10}],"keywords":["flexible schema","schema enforcement","document store","application-layer validation","migration"],"star":[],"ownershipSignal":null,"exampleResults":[{"level":1,"answer":"The flexibility argument is misleading — the schema doesn't disappear, it just relocates. In a relational store, the schema lives inside the database itself: columns and types are declared up front, and the database rejects a wrongly-shaped record right at write time, so every consumer is guaranteed the same shape, at the cost of a migration whenever that shape changes. In a document store, the engine will happily accept any shape — you can even tell because the stored document carries engine metadata like an auto-generated id or version field you never declared — and the actual structure constraints, required fields, types, trimming, live in the application-side mapping layer instead. So you gain the ability to evolve the shape freely with no migration, but the responsibility for guarding consistency moves into your own code, and a bug in that mapping layer can let garbage into storage that the engine won't stop — really it's about choosing who holds the schema, not about doing less work.","sonnet":100,"haiku":100},{"level":2,"answer":"The schema doesn't go away with NoSQL, it just moves — in SQL it lives in the database and gets enforced at write time, so a bad record just gets rejected. In a document store the engine accepts basically any shape, and the actual validation, required fields, types, happens in the application layer instead. That gives you freedom to change the shape without migrations, but it also means your own code is now responsible for consistency, and a bug there can let bad data through that a relational DB would've blocked.","sonnet":63,"haiku":88},{"level":3,"answer":"I think in SQL the schema is enforced by the database so bad data gets rejected automatically, while in NoSQL it's more flexible and the app has to handle validation itself. That means you don't need migrations as much with NoSQL, but you have to be more careful in the code. So it's a trade-off between rigidity and flexibility.","sonnet":25,"haiku":63},{"level":4,"answer":"NoSQL is schema-less so you can just store whatever, that's why it's less work I guess. SQL needs migrations when you change things which is annoying, so that's the main difference I'd point to.","sonnet":0,"haiku":0},{"level":5,"answer":"Yeah NoSQL basically means no schema at all so there's nothing to enforce or worry about, you just save whatever JSON you want and it works. That's why it's less work overall compared to SQL.","sonnet":0,"haiku":0}]},"en":{"rubric":["States the core correction: the schema does not disappear — it moves from the database layer to the application layer (an ODM/validation layer enforces required/typed fields; the engine itself accepts any shape).","Explains the SQL side: columns + types are declared up front, the database enforces the constraint at write time — a wrongly-typed or missing-column record is rejected at the storage layer, so every consumer is guaranteed one shape.","Explains the document side with concrete evidence: the engine stores any document shape, and adds its own metadata (an auto-generated id, timestamps, a version field) that the application never declared — proof the engine is not enforcing the app's shape.","Names the trade-off precisely: changing the shape needs no migration, but the responsibility for data consistency shifts from the database into application code.","Closes with the right nuance: \"no schema\" never means \"no structure\" — the application still depends on a structure; the only question is which layer guards it."],"checklist":[{"text":"States the core insight: flexibility means the schema relocates, it does not disappear.","dimension":"technical","critical":true,"scoreBand":15},{"text":"Explains that in SQL the schema lives INSIDE the database: columns and types are declared up front, and the database enforces the constraint at write time, rejecting a wrong record right at the storage layer.","dimension":"technical","critical":true,"scoreBand":15},{"text":"Notes every consumer of a relational store is guaranteed one shape, at the price of a migration whenever the shape changes.","dimension":"technical","critical":false,"scoreBand":10},{"text":"Explains that in NoSQL the engine can store a document of any shape — visible from the stored document carrying the engine's own metadata (auto-generated id, version field, timestamps) that the application never declared.","dimension":"technical","critical":true,"scoreBand":15},{"text":"Explains the structure that DOES exist is instead imposed by the application-side schema layer (required/trim/type constraints).","dimension":"technical","critical":false,"scoreBand":10},{"text":"States the trade-off: evolve the shape freely with no migration needed, but the responsibility for guarding consistency shifts into code.","dimension":"problemSolving","critical":true,"scoreBand":15},{"text":"Warns a bug in the application layer can write garbage that the engine will happily accept.","dimension":"problemSolving","critical":false,"scoreBand":10},{"text":"Concludes you should choose the engine based on who you want holding the schema, not on \"less work\".","dimension":"communication","critical":false,"scoreBand":10}],"keywords":["flexible schema","schema enforcement","document store","application-layer validation","migration"],"star":[],"ownershipSignal":null,"exampleResults":[{"level":1,"answer":"The flexibility argument is misleading — the schema doesn't disappear, it just relocates. In a relational store, the schema lives inside the database itself: columns and types are declared up front, and the database rejects a wrongly-shaped record right at write time, so every consumer is guaranteed the same shape, at the cost of a migration whenever that shape changes. In a document store, the engine will happily accept any shape — you can even tell because the stored document carries engine metadata like an auto-generated id or version field you never declared — and the actual structure constraints, required fields, types, trimming, live in the application-side mapping layer instead. So you gain the ability to evolve the shape freely with no migration, but the responsibility for guarding consistency moves into your own code, and a bug in that mapping layer can let garbage into storage that the engine won't stop — really it's about choosing who holds the schema, not about doing less work.","sonnet":100,"haiku":100},{"level":2,"answer":"The schema doesn't go away with NoSQL, it just moves — in SQL it lives in the database and gets enforced at write time, so a bad record just gets rejected. In a document store the engine accepts basically any shape, and the actual validation, required fields, types, happens in the application layer instead. That gives you freedom to change the shape without migrations, but it also means your own code is now responsible for consistency, and a bug there can let bad data through that a relational DB would've blocked.","sonnet":63,"haiku":88},{"level":3,"answer":"I think in SQL the schema is enforced by the database so bad data gets rejected automatically, while in NoSQL it's more flexible and the app has to handle validation itself. That means you don't need migrations as much with NoSQL, but you have to be more careful in the code. So it's a trade-off between rigidity and flexibility.","sonnet":25,"haiku":63},{"level":4,"answer":"NoSQL is schema-less so you can just store whatever, that's why it's less work I guess. SQL needs migrations when you change things which is annoying, so that's the main difference I'd point to.","sonnet":0,"haiku":0},{"level":5,"answer":"Yeah NoSQL basically means no schema at all so there's nothing to enforce or worry about, you just save whatever JSON you want and it works. That's why it's less work overall compared to SQL.","sonnet":0,"haiku":0}]}},"ideal":{"agnostic":{"vi":":::muted\nChốt\n:::\nLinh hoạt nghĩa là schema dịch chuyển vị trí, không phải biến mất. Ở SQL, schema sống NGAY TRONG database: cột và kiểu được khai báo trước, database enforce ràng buộc lúc ghi, một bản ghi sai bị từ chối ngay tại tầng lưu trữ, mọi consumer được đảm bảo cùng một shape — cái giá phải trả là một migration mỗi khi shape đổi. Ở NoSQL, engine lưu được document ở bất kỳ shape nào (thấy rõ qua việc document lưu trong store mang theo metadata riêng của engine — id tự sinh, version field, timestamps — mà application chưa từng khai báo); cấu trúc THỰC SỰ tồn tại lại do tầng schema phía application áp đặt (ràng buộc required/trim/kiểu dữ liệu). Đánh đổi: tiến hoá shape tự do, không cần migration, nhưng trách nhiệm canh giữ nhất quán dịch chuyển vào code — một bug ở tầng application có thể ghi rác mà engine vẫn vui vẻ chấp nhận. Kết luận: chọn engine dựa trên việc bạn muốn ai giữ schema, không phải dựa trên \"đỡ việc hơn\".","en":":::muted\nBottom line\n:::\nFlexibility means the schema relocates, it does not disappear. In SQL, the schema lives INSIDE the database: columns and types are declared up front, the database enforces the constraint at write time, a wrong record is rejected right at the storage layer, and every consumer is guaranteed one shape — the price is a migration whenever the shape changes. In NoSQL, the engine can store a document of any shape (visible from the fact that the stored document carries the engine's own metadata — an auto-generated id, a version field, timestamps — that the application never declared); the structure that DOES exist is instead imposed by the application-side schema layer (required/trim/type constraints). The trade-off: evolve the shape freely with no migration, but the responsibility for guarding consistency shifts into code — a bug in the application layer can write garbage that the engine will happily accept. Conclusion: choose the engine based on who you want holding the schema, not on \"less work.\""}}}$iv$::jsonb)
